import { add_remove_user_to_team } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    memberdelete: Boolean,
    subscriberitem: Object,
    dashboarditems: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    memberdelete: {
      async handler() {
        // console.log(this.subscriberitem);
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(add_remove_user_to_team, {
          input: {
            admin_user_id: this.dashboarditems.team_owner_id,
            organization_id: data.organization.organization_id,
            team_id: this.dashboarditems.team_id,
            action_type: "REMOVE",
            user_id: this.subscriberitem.user_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.add_remove_user_to_team);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
